// 1. 定义必要的环境变量
window.Joe = window.Joe || { isMobile: false };
window.ThemeConfig = window.ThemeConfig || {
  enable_offscreen_tip: true,
  blog_url: '{{ .Site.BaseURL }}',
  offscreen_title_leave: '歪，你去哪里了？',
  offscreen_title_back: '(つェ⊂)咦，又回来了~'
};

// 2. 定义函数（如果尚未定义）
function offscreenTip() {
  if (Joe.isMobile || !ThemeConfig.enable_offscreen_tip) return;
  const e = document.title;
  let t = null;
  document.addEventListener("visibilitychange", (function() {
    location.href.indexOf(ThemeConfig.blog_url) > 0 || "/" !== location.pathname || 
    (document.hidden ? 
      (document.title = ThemeConfig.offscreen_title_leave || "歪，你去哪里了？", clearTimeout(t)) : 
      (document.title = ThemeConfig.offscreen_title_back || "(つェ⊂)咦，又回来了!", 
        t = setTimeout((function() {
          document.title = e
        }), 2000)
      )
    )
  }))
}

// 3. 调用函数
offscreenTip();